output_text:
[
  {
    "id": "entry_cart_pickup_required",
    "text": "A shopper should begin by taking the cart from the entry cart station rather than treating the entry interaction as optional or as an item pickup.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "no_hand_item_collection",
    "text": "Items should not be picked up or carried by hand; item collection is expected to be done with a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "item_pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_northwest_bay",
    "text": "Any cart taken for shopping must eventually be returned to the northwest cart bay before the shopper leaves.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_in_bay": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "pushing_cart"
        },
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "northwest_cart_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper may put down the cart only at the designated northwest return bay.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_event": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_event",
          {
            "not": "northwest_cart_bay"
          }
        ]
      }
    }
  },
  {
    "id": "drop_cart_immediately_at_bay",
    "text": "Upon arriving at the northwest return bay while still pushing a cart, the shopper should leave the cart there immediately.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_drop": {
          "pre": "LEAVE_CART",
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "northwest_cart_bay",
          "pushing_cart",
          {
            "not": "LEAVE_CART"
          }
        ]
      }
    }
  },
  {
    "id": "exit_without_cart",
    "text": "The shopper should exit the store without the cart, leaving it behind before checkout.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_attempt": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_attempt",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "no_more_interactions_after_cart_return",
    "text": "After the cart has been parked in the return bay, the shopper should proceed to the exit without further store interactions.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "no_east_from_west_wall_with_cart",
    "text": "While pushing a cart on the west-wall return lane, the shopper should not turn east into the store aisles.",
    "abstraction": {
      "state_properties": {
        "west_wall_return_lane": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_turns_east_from_west_wall": {
          "pre": {
            "and": [
              "west_wall_return_lane",
              "pushing_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_turns_east_from_west_wall"
    }
  }
]
